insert into markers (skill_id, phrase, translation_nl, note)
select s.id, d.phrase, d.nl, d.note
from (values
  ('imperfecto', 'siempre', 'altijd', null),
  ('imperfecto', 'cada vez', 'elke keer', null),
  ('imperfecto', 'antes', 'vroeger', null),
  ('imperfecto', 'normalmente', 'gewoonlijk, normaal', null),
  ('imperfecto', 'soler', 'gewoon zijn om', null),
  ('imperfecto', 'todos los días', 'elke dag', null),
