  ('imperfecto', 'porque', 'omdat', 'porque + imperfecto geeft uitleg of beschrijving.'),
  ('imperfecto', 'sustantivo + que', 'zelfstandig naamwoord + dat/die', 'Beschrijft het zelfstandig naamwoord ervoor.'),
