  ('indefinido', 'hace x días', 'x dagen geleden', null),
  ('indefinido', 'hace x semanas', 'x weken geleden', null),
  ('indefinido', 'hace x meses', 'x maanden geleden', null),
  ('indefinido', 'hace x años', 'x jaren geleden', null),
  ('indefinido', 'el otro día', 'toen die dag', null),
